import 'dart:math';
import 'package:equatable/equatable.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:locallink/core/models/attachment.dart';import 'package:locallink/features/files/data/models/file_transfer_models.dart';import 'package:locallink/features/files/domain/file_transfer_repository_contract.dart';import 'package:locallink/core/diagnostics/app_diagnostics.dart';
final class FileTransferState extends Equatable{final List<TransferProgress> operations;const FileTransferState({this.operations=const []});TransferProgress? progressOf(String id){for(final progress in operations){if(progress.operationId==id)return progress;}return null;}FileTransferState copyWith({List<TransferProgress>? operations})=>FileTransferState(operations:operations??this.operations);@override List<Object?> get props=>[operations];}
final class FileTransferBloc extends Cubit<FileTransferState>{final FileTransferRepositoryContract repository;final Map<String,TransferProgress> _map={};final Set<String> _cancelRequested={};final Map<String,String> _directFileIds={};FileTransferBloc({required this.repository}):super(const FileTransferState());List<TransferProgress> get operations=>List.unmodifiable(_map.values);TransferProgress? progressOf(String id)=>_map[id];Future<List<PickedFile>> pickFiles({String mimeType='*/*',bool allowMultiple=false})=>repository.pickFiles(mimeType:mimeType,allowMultiple:allowMultiple);Future<Attachment> upload(PickedFile file,{String? clientFileId}) async{final id=_newId();_start(id,FileTransferDirection.upload);try{final a=await repository.upload(file,clientFileId:clientFileId,operationId:id,onProgress:(p)=>_update(id,p));_finish(id,FileTransferStatus.completed);return a;}on FileTransferCancelledException{_finish(id,FileTransferStatus.cancelled);rethrow;}catch(e){_fail(id,e);rethrow;}finally{_cancelRequested.remove(id);}}Future<void> sendDirectFile({required String recipientId,required String messageId,required String fileId,required PickedFile file}) async{final id=_newId();_directFileIds[id]=fileId;_start(id,FileTransferDirection.direct);try{await repository.sendDirectFile(recipientId:recipientId,messageId:messageId,fileId:fileId,file:file);_finish(id,FileTransferStatus.completed);}catch(e){_fail(id,e);rethrow;}finally{_directFileIds.remove(id);}}Future<String> download(Attachment attachment,{required String messageId,String? groupMessageId}) async{final id=_newId();_start(id,FileTransferDirection.download);try{final path=groupMessageId!=null?await repository.downloadForGroupMessage(groupMessageId,attachment,operationId:id,onProgress:(p)=>_update(id,p)):await repository.downloadForMessage(messageId,attachment,operationId:id,onProgress:(p)=>_update(id,p));_finish(id,FileTransferStatus.completed);return path;}on FileTransferCancelledException{_finish(id,FileTransferStatus.cancelled);rethrow;}catch(e){_fail(id,e);rethrow;}finally{_cancelRequested.remove(id);}}Future<void> cancel(String id) async{final p=_map[id];if(p==null)return;_cancelRequested.add(id);_update(id,p.copyWith(status:FileTransferStatus.cancelled));final directFileId=_directFileIds[id];if(directFileId!=null){await repository.cancelDirectFile(directFileId);}else{await repository.cancel(id);}}void clearFinished(){_map.removeWhere((_,v)=>v.status==FileTransferStatus.completed||v.status==FileTransferStatus.failed||v.status==FileTransferStatus.cancelled);_emit();}void _start(String id,FileTransferDirection d){AppDiagnostics.instance.record('files','transfer_started',data:{'status':'running'});_map[id]=TransferProgress(operationId:id,direction:d,completed:0,total:0,status:FileTransferStatus.running);_emit();}void _update(String id,TransferProgress p){if(_cancelRequested.contains(id))return;_map[id]=p;_emit();}void _finish(String id,FileTransferStatus s){AppDiagnostics.instance.record('files','transfer_finished',data:{'status':s.name});final p=_map[id];if(p==null)return;_map[id]=p.copyWith(status:s,error:null);_emit();}void _fail(String id,Object e){AppDiagnostics.instance.recordException('files','transfer_failed',e,reasonCode:'transfer_failed');final p=_map[id];if(p==null)return;_map[id]=p.copyWith(status:FileTransferStatus.failed,error:e.toString().replaceFirst('Exception: ',''));_emit();}void _emit()=>emit(FileTransferState(operations:List.unmodifiable(_map.values)));String _newId(){final r=Random.secure();return '${DateTime.now().microsecondsSinceEpoch}-${List.generate(12,(_)=>r.nextInt(16).toRadixString(16)).join()}';}}
